WITH base AS (SELECT *, UPPER(TRIM(full_name)) AS full_name_normalized FROM employees WHERE job_title <> 'Designer'), Agg AS (SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END AS hire_cohort, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(level))) AS level_values, SORT_ARRAY(COLLECT_SET(level)) AS level_list FROM base GROUP BY CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT hire_cohort, level_values, level_list FROM Agg;
